SCENE_CSS = "/* Decorative 18-horse arc: zero provider calls, no JS, no storage, no betting logic. */\n.arc-race-scene{position:relative;height:120px;margin:0 0 14px;overflow:hidden;border:1px solid #58708a;border-radius:14px;background:#101f35;isolation:isolate}\n.arc-race-scene-svg{display:block;width:100%;height:100%}\n.arc-scene-caption{position:absolute;left:8px;right:8px;bottom:4px;text-align:center;font-size:10px;line-height:1.25;color:#e3e8f0;text-shadow:0 1px 4px #06111b;background:#07131d9e;padding:2px;border-radius:5px}\n.arc-horse-moving use{transform-origin:center;animation:arc-horse-gallop .36s ease-in-out infinite alternate}\n.arc-horse-moving:nth-child(3n) use{animation-delay:-.18s}\n@keyframes arc-horse-gallop{from{transform:translateY(0) rotate(-1deg)}to{transform:translateY(-2.3px) rotate(2deg)}}\n.arc-horse-still-group{display:none}\n@media(prefers-reduced-motion:reduce){.arc-horse-motion{display:none}.arc-horse-still-group{display:inline}.arc-horse-moving use{animation:none}}\n@media(max-width:370px){.arc-race-scene{height:106px}.arc-scene-caption{font-size:9px}}\n"
ANIMATED_HORSE_COUNT = 18
